import { aeroBrand, aeroLogo, aeroSwitcher } from './aero-brands.js';

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inBrowser = typeof window !== 'undefined' && typeof document !== 'undefined';

/** Brand stage for this page: window.AERO_BRAND_STAGE, or <html data-aero-stage>. Anything but "ascent-internal" is production. */
export function pageStage() {
  if (!inBrowser) return '';
  return window.AERO_BRAND_STAGE || document.documentElement.dataset.aeroStage || '';
}
/** Per-pillar link overrides (local previews): window.AERO_URLS = { ascent, birdbrains, chirp }. */
export function pageUrls() {
  return (inBrowser && window.AERO_URLS) || {};
}

/** A locked Aero logo as an SVG string. variant: "kinetic", "origami", or "isometric" (default). */
export function logoSvg(key, variant = 'isometric', opts = {}) {
  const art = aeroLogo(key, variant, opts.stage);
  const size = opts.size ? ` width="${esc(opts.size)}" height="${esc(opts.size)}"` : '';
  const a11y = opts.title ? ` role="img" aria-label="${esc(opts.title)}"` : ' aria-hidden="true"';
  return `<svg class="aero-logo${opts.className ? ' ' + esc(opts.className) : ''}" viewBox="${art.viewBox}" fill="none" xmlns="http://www.w3.org/2000/svg"${size}${a11y} focusable="false">${art.markup}</svg>`;
}

/** Interactive 2D Origami <-> 3D Isometric extrusion stage HTML. */
export function morphStageHtml(key, opts = {}) {
  const stage = opts.stage || '';
  const b = aeroBrand(key, stage);
  const showGrid = opts.grid !== false;
  const grid = showGrid ? `<svg class="aero-morph__grid" viewBox="0 0 48 48" fill="none" aria-hidden="true">
    <rect x="2" y="2" width="44" height="44" stroke="#94A3B8" stroke-width="0.6" stroke-dasharray="2 2"/>
    <circle cx="24" cy="24" r="20" stroke="#94A3B8" stroke-width="0.6"/>
    <line x1="0" y1="24" x2="48" y2="24" stroke="#94A3B8" stroke-width="0.5"/>
    <line x1="24" y1="0" x2="24" y2="48" stroke="#94A3B8" stroke-width="0.5"/>
    <line x1="2" y1="36" x2="46" y2="12" stroke="#38BDF8" stroke-width="0.55" stroke-dasharray="2 2"/>
    <line x1="2" y1="12" x2="46" y2="36" stroke="#38BDF8" stroke-width="0.55" stroke-dasharray="2 2"/>
  </svg>` : '';
  const crease = `<svg class="aero-morph__crease" viewBox="0 0 48 48" fill="none" aria-hidden="true">
    <line x1="24" y1="6" x2="24" y2="42" stroke="${esc(b.primary)}" stroke-width="0.9" stroke-dasharray="1.5 1.5"/>
    <line x1="6" y1="24" x2="42" y2="24" stroke="${esc(b.primary)}" stroke-width="0.9" stroke-dasharray="1.5 1.5"/>
    <line x1="12" y1="12" x2="36" y2="36" stroke="${esc(b.primary)}" stroke-width="0.9" stroke-dasharray="1.5 1.5"/>
  </svg>`;
  return `<div class="aero-morph__stage">${grid}<div class="aero-morph__shadow" aria-hidden="true"></div><div class="aero-morph__flat">${crease}${logoSvg(key, 'origami', { stage, title: opts.title })}</div><div class="aero-morph__3d">${logoSvg(key, 'isometric', { stage })}</div></div>`;
}

/**
 * The shared Aero global header as an HTML string.
 * o: { brand, stage, urls, home, coord, nav, actions, stack }
 *   nav / actions : the app's own HTML for those two regions (optional)
 *   stack         : on small screens, drop nav/actions to a second row
 */
export function headerHtml(o) {
  const stage = o.stage || '';
  const urls = o.urls || {};
  const isAero = o.brand === 'aero';
  const me = aeroBrand(o.brand, stage);
  const items = aeroSwitcher(o.brand, stage, urls);
  const aeroUrl = isAero ? (o.home || '/') : (urls.aero || aeroBrand('aero', stage).url || '/');
  const menuId = `aero-eco-${me.key}`;
  const rows = items.map((i) => `
        <a class="aero-switcher__item" href="${esc(i.current ? (o.home || '/') : i.href)}" data-aero-brand="${esc(i.paletteKey)}"${i.current ? ' aria-current="true"' : ''}>
          ${logoSvg(i.key, 'isometric', { stage })}
          <span><span class="aero-switcher__name">${esc(i.name)}</span><span class="aero-switcher__role">${esc(i.role)}</span></span>
          <span class="aero-switcher__meta">${i.current ? '<span class="aero-switcher__here">Here</span>' : ''}<span>${esc(i.domain)}</span></span>
        </a>`).join('');
  const lockupLabel = isAero ? 'Aero, home' : `${me.name} by Aero, home`;
  const lockupBy = isAero ? 'SYS-00' : 'by Aero';
  return `<header class="aero-header${o.stack ? ' aero-header--stack' : ''}" data-aero-header>
  <div class="aero-header__bar">
    <div class="aero-switcher" data-aero-switcher>
      <button type="button" class="aero-switcher__pill" aria-haspopup="true" aria-expanded="false" aria-controls="${menuId}" aria-label="Aero ecosystem: switch app">
        ${logoSvg('aero', 'isometric')}<span class="aero-switcher__label">Aero</span>
        <svg class="aero-switcher__chev" viewBox="0 0 10 10" fill="none" aria-hidden="true"><path d="M2 3.5L5 6.5L8 3.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
      </button>
      <div class="aero-switcher__menu" id="${menuId}" hidden>
        <p class="aero-switcher__head"><span>Aero ecosystem</span><span>SYS-00</span></p>${rows}
        <a class="aero-switcher__foot" href="${esc(aeroUrl)}"${isAero ? ' aria-current="true"' : ''}>${logoSvg('aero', 'isometric')}<span>One system, three tools.</span><span class="aero-switcher__foot-go">${isAero ? 'Here' : 'Overview →'}</span></a>
      </div>
    </div>
    <a class="aero-lockup" href="${esc(o.home || '/')}" aria-label="${esc(lockupLabel)}">
      ${logoSvg(o.brand, 'isometric', { stage })}
      <span class="aero-lockup__name">${esc(me.name)}</span><span class="aero-lockup__by">${esc(lockupBy)}</span>
    </a>${o.nav ? `
    <nav class="aero-header__nav" aria-label="Primary">${o.nav}</nav>` : ''}${o.actions ? `
    <div class="aero-header__actions">${o.actions}</div>` : ''}${o.coord ? `
    <span class="aero-header__coord" aria-hidden="true">${esc(o.coord)}</span>` : ''}
  </div>
</header>`;
}

/** Shared ecosystem footer strip as an HTML string. */
export function footerHtml(o) {
  const stage = o.stage || '';
  const urls = o.urls || {};
  const isAero = o.brand === 'aero';
  const me = aeroBrand(o.brand, stage);
  const aeroUrl = isAero ? (o.home || '/') : (urls.aero || aeroBrand('aero', stage).url || '/');
  const others = aeroSwitcher(o.brand, stage, urls)
    .filter((i) => !i.current)
    .map((i) => `<a href="${esc(i.href)}">${esc(i.name)}</a>`)
    .join(' ');
  const label = isAero ? 'Aero · Parent system' : `${me.name} by Aero`;
  return `<div class="aero-foot">${logoSvg('aero', 'isometric')}<span>${esc(label)}</span><span class="aero-foot__sep" aria-hidden="true">/</span>${isAero ? '<span>Tools:</span>' : `<a href="${esc(aeroUrl)}">Aero overview</a><span class="aero-foot__sep" aria-hidden="true">/</span><span>Also from Aero:</span>`} ${others}<span class="aero-coord" style="margin-left:auto" aria-hidden="true">SYS-00 · AERO.SUITE</span></div>`;
}

/** Open/close behaviour for every ecosystem switcher under root. Safe to call more than once. */
export function wireHeader(root) {
  if (!inBrowser) return;
  (root || document).querySelectorAll('[data-aero-switcher]').forEach((sw) => {
    if (sw.dataset.aeroWired) return;
    sw.dataset.aeroWired = '1';
    const btn = sw.querySelector('.aero-switcher__pill');
    const menu = sw.querySelector('.aero-switcher__menu');
    if (!btn || !menu) return;
    const set = (open) => { menu.hidden = !open; btn.setAttribute('aria-expanded', String(open)); };
    btn.addEventListener('click', () => set(menu.hidden));
    document.addEventListener('pointerdown', (e) => { if (!sw.contains(e.target)) set(false); });
    sw.addEventListener('focusout', (e) => { if (e.relatedTarget && !sw.contains(e.relatedTarget)) set(false); });
    sw.addEventListener('keydown', (e) => {
      const links = Array.from(menu.querySelectorAll('a'));
      const at = links.indexOf(document.activeElement);
      if (e.key === 'Escape' && !menu.hidden) { set(false); btn.focus(); }
      else if (e.key === 'ArrowDown' && links.length) { e.preventDefault(); set(true); links[(at + 1) % links.length].focus(); }
      else if (e.key === 'ArrowUp' && !menu.hidden && links.length) { e.preventDefault(); links[(at - 1 + links.length) % links.length].focus(); }
    });
  });
}

if (inBrowser && 'customElements' in window) {
  /** <aero-logo brand="aero|ascent|birdbrains|chirp" variant="isometric" size="48" label="…"> */
  class AeroLogo extends HTMLElement {
    static get observedAttributes() { return ['brand', 'variant', 'size', 'label']; }
    connectedCallback() { this.render(); }
    attributeChangedCallback() { if (this.isConnected) this.render(); }
    render() {
      this.innerHTML = logoSvg(this.getAttribute('brand') || 'aero', this.getAttribute('variant') || 'isometric', {
        size: this.getAttribute('size') || '', title: this.getAttribute('label') || '', stage: pageStage(),
      });
    }
  }

  /** <aero-global-header brand="chirp" home="#today" coord="CHP-00" stack>
        <div slot="nav">…</div><div slot="actions">…</div>
      </aero-global-header>
      Slotted nodes are moved, not copied, so listeners already attached to them keep working. */
  class AeroGlobalHeader extends HTMLElement {
    connectedCallback() {
      if (this.dataset.rendered) { wireHeader(this); return; }
      const nav = this.querySelector(':scope > [slot="nav"]');
      const actions = this.querySelector(':scope > [slot="actions"]');
      const tpl = document.createElement('template');
      tpl.innerHTML = headerHtml({
        brand: this.getAttribute('brand') || 'aero', stage: pageStage(), urls: pageUrls(),
        home: this.getAttribute('home') || '/', coord: this.getAttribute('coord') || '',
        stack: this.hasAttribute('stack'), nav: nav ? ' ' : '', actions: actions ? ' ' : '',
      });
      const header = tpl.content.firstElementChild;
      if (nav) header.querySelector('.aero-header__nav').replaceChildren(...nav.childNodes);
      if (actions) header.querySelector('.aero-header__actions').replaceChildren(...actions.childNodes);
      this.replaceChildren(header);
      this.dataset.rendered = '1';
      wireHeader(this);
    }
  }

  class AeroFooter extends HTMLElement {
    connectedCallback() {
      if (this.dataset.rendered) return;
      this.innerHTML = footerHtml({
        brand: this.getAttribute('brand') || 'aero', stage: pageStage(), urls: pageUrls(),
        home: this.getAttribute('home') || '/',
      });
      this.dataset.rendered = '1';
    }
  }

  class AeroMorph extends HTMLElement {
    connectedCallback() {
      if (this.dataset.rendered) return;
      const brand = this.getAttribute('brand') || 'aero';
      const title = this.getAttribute('label') || '';
      this.classList.add('aero-morph');
      if (!this.hasAttribute('data-morph-hover') && !this.hasAttribute('data-morph-default')) {
        this.setAttribute('data-morph-default', '3d');
      }
      this.innerHTML = morphStageHtml(brand, { stage: pageStage(), title, grid: this.getAttribute('grid') !== 'false' });
      this.addEventListener('click', () => {
        if (this.getAttribute('data-morph-default') === '3d') this.classList.toggle('aero-morph--flat');
        else this.classList.toggle('aero-morph--3d');
      });
      this.dataset.rendered = '1';
    }
  }

  if (!customElements.get('aero-logo')) customElements.define('aero-logo', AeroLogo);
  if (!customElements.get('aero-global-header')) customElements.define('aero-global-header', AeroGlobalHeader);
  if (!customElements.get('aero-footer')) customElements.define('aero-footer', AeroFooter);
  if (!customElements.get('aero-morph')) customElements.define('aero-morph', AeroMorph);
  // Headers pre-rendered at build time are plain markup: wire them once the DOM is ready.
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => wireHeader(document));
  else wireHeader(document);
}
